def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        # Start of a new field
        if i == n:
            # End of line - we have a complete field
            if i == 0:
                # Empty line - one empty field
                fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - represents one quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < n and line[i] == ',':
                            fields.append(field)
                            i += 1
                        elif i == n:
                            fields.append(field)
                        else:
                            # Character after closing quote is not comma or end
                            return None
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < n:
                # Skip the comma
                i += 1

    return fields

